\title[Interval hints are priced by coverage and width]{Interval Hints Are Priced by Coverage and Width:\\ An Exact Additive Law for Hinted Sequential Search}
\author{Aristotle}
\date{October 2026}

\begin{document}

\begin{abstract}
An oracle announces a window of $W$ out of $M$ candidate cells and claims that the hidden target lies in the window with probability $\alpha$. We study the value of such \emph{interval hints} for sequential search, where cells are probed one at a time and the cost is the expected number of probes. Under a uniform prior and truthful conditioning we prove that the committed procedure (scan the window first, then the rest) has expected cost exactly $\tfrac12\bigl(W+1+(1-\alpha)M\bigr)$, hence speedup
\[
S(M,W,\alpha)=\frac{M+1}{(1-\alpha)M+W+1}
\]
over blind search, with continuum limit $1/(1-\alpha+w)$, $w=W/M$. Coverage and width thus enter \emph{additively}, not multiplicatively; equal-value hints trade one cell of width for exactly $1/M$ of coverage, and the speedup is capped by a coverage ceiling $1/(1-\alpha)$ and a width ceiling $(M+1)/(W+1)$. The committed procedure is Bayes-optimal among all $M!$ orders if and only if $\alpha\ge w$. We calibrate an observed $5.19\times$ gain: for windows of relative width $2$--$5\%$ it corresponds to coverage strictly between $0.82$ and $0.86$, so a $90\%$ reading overprices it. For the min-law prior $P(J=j)=(2(M-j)+1)/M^2$ we derive the optimal blind cost $(M+1)(2M+1)/(6M)$ and the exact perfect-coverage block-hint speedup $(M+1)(2M+1)/((W+1)(3M-W+1))\to 2/(w(3-w))$. Finally we prove concavity of the Bayes search cost and an exact regret $(\alpha-\beta)M/2$ for misspecified coverage.
\end{abstract}

\maketitle

\section{Introduction}

Sequential search with side information is ubiquitous: debugging guided by fault-localization heuristics, key search guided by leaked partial information, diagnostic test scheduling guided by a classifier, sky surveys guided by a prior. A common form of side information is an \emph{interval hint}: a designated set of candidates together with a reliability. Such hints are often described informally (``it is in the first few percent, about nine times out of ten''), and observed speedups are explained by an ``equivalent'' hint.

This paper gives an exact dictionary between hints and speedups. The motivating question came from a structured search in which ordering candidates by magnitude produced an observed gain of about $5.19\times$, with the target distributed as the minimum of two independent uniform draws. An informal reading equated that gain to an oracle knowing the target's position within a $2$--$5\%$-wide window at roughly $90\%$ reliability. We identify exactly how coverage and width combine, when the natural window-first procedure is optimal, and what can be proved exactly for the tilted min-law prior.

\section{Model and definitions}

Cells are indexed $0,\dots,M-1$; a hidden target $J$ occupies exactly one cell.

\begin{definition}[Probe cost]
A \emph{probe order} is a permutation $\sigma$ of the cells; probe number $i\ge1$ inspects $\sigma(i)$. For nonnegative weights $q$ the \emph{probe cost} is $C(q,\sigma)=\sum_{i=1}^M i\,q_{\sigma(i)}$. If $q$ is the law of $J$, this is the expected number of probes.
\end{definition}

\begin{definition}[Bayes cost; blind cost]
$\opt(q)=\min_\sigma C(q,\sigma)$ over all $M!$ orders; a minimizer is \emph{Bayes-optimal}. Under the uniform prior every order costs $\blind(M)=(M+1)/2$.
\end{definition}

\begin{definition}[Interval hint]
An interval hint of width $0<W<M$ and coverage $\alpha\in[0,1]$ designates the window $\{0,\dots,W-1\}$ (after relabelling) and asserts $P(J\in\text{window})=\alpha$. From the uniform prior the truthful posterior is
\[
h_j=\begin{cases}\alpha/W,& j<W,\\ (1-\alpha)/(M-W),& j\ge W,\end{cases}
\]
a probability vector. We write $w=W/M$.
\end{definition}

\begin{definition}[Committed procedure; speedup]
The committed procedure probes the window, then the complement, each in increasing order; its cost is $\hint(M,W,\alpha)=C(h,\id)$, and the speedup is $S(M,W,\alpha)=\blind(M)/\hint(M,W,\alpha)$.
\end{definition}

\begin{definition}[Min-law]
If $p,q$ are independent uniform on $\{1,\dots,M\}$, the law of $J=\min(p,q)$ is $\mu_M(j)=(2(M-j)+1)/M^2$, $j=1,\dots,M$.
\end{definition}

\section{Greedy order is Bayes-optimal}

\begin{theorem}[Greedy optimality]\label{thm:greedy}
If $i\mapsto q_{\tau(i)}$ is non-increasing, then $C(q,\tau)\le C(q,\sigma)$ for all $\sigma$; hence $\opt(q)=C(q,\tau)$.
\end{theorem}
\begin{proof}[Proof sketch]
Positions $1,\dots,M$ increase while $q_{\tau(i)}$ does not increase, so the sequences are oppositely ordered. By the rearrangement inequality $\sum_i i\,q_{\tau(i)}\le\sum_i i\,q_{\tau(\pi(i))}$ for every permutation $\pi$; take $\pi=\tau^{-1}\sigma$.
\end{proof}

\section{The exact two-number law}

For a two-level profile ($a$ on the first $W$ positions, $b$ on the remaining $M-W$), induction on $M\ge W$ gives
\begin{equation}\label{eq:window}
\sum_{i=0}^{M-1}(i+1)\,[a \text{ if } i<W \text{ else } b]=a\frac{W(W+1)}2+b\frac{(M-W)(M+W+1)}2 .
\end{equation}

\begin{theorem}[Exact hinted cost and speedup]\label{thm:exact}
For $0<W<M$ and real $\alpha$,
\[
\hint(M,W,\alpha)=\frac{W+1+(1-\alpha)M}{2},\qquad S(M,W,\alpha)=\frac{M+1}{(1-\alpha)M+W+1}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Apply \eqref{eq:window} with $a=\alpha/W$, $b=(1-\alpha)/(M-W)$ to get $\tfrac12\alpha(W+1)+\tfrac12(1-\alpha)(M+W+1)$, which simplifies as stated; divide $(M+1)/2$ by it.
\end{proof}

\section{Optimality of the committed procedure}

\begin{theorem}[Bayes optimality for $\alpha\ge w$]\label{thm:opt}
If $W\le\alpha M$, then $\hint(M,W,\alpha)\le C(h,\sigma)$ for all $\sigma$, so $\opt(h)=\hint(M,W,\alpha)$.
\end{theorem}
\begin{proof}[Proof sketch]
$(1-\alpha)/(M-W)\le\alpha/W$ is equivalent to $W\le\alpha M$. Then $h$ read in committed order is non-increasing; apply Theorem~\ref{thm:greedy}.
\end{proof}

\begin{theorem}[Sharpness]\label{thm:sharp}
If $\alpha M<W$, transposing cells $W-1$ and $W$ in the committed order strictly lowers the cost; the committed procedure is not Bayes-optimal.
\end{theorem}
\begin{proof}[Proof sketch]
Only probes $W$ and $W+1$ change. Committed minus transposed cost equals $\frac{1-\alpha}{M-W}-\frac{\alpha}{W}$, which is positive iff $\alpha M<W$.
\end{proof}

Hence the committed procedure is Bayes-optimal \emph{if and only if} $\alpha\ge w$.

\begin{example}
For $M=6$, $W=2$, enumeration of all $720$ orders gives: $\alpha=1/2$: committed $3$ $=$ optimum; $\alpha=1/3$: committed $7/2$ $=$ optimum; $\alpha=1/4$: committed $15/4$, optimum $13/4$ (probe the four outside cells first).
\end{example}

\section{Ceilings, exchange rate and continuum law}

\begin{theorem}\label{thm:ceil}
Let $0<W<M$.
\begin{enumerate}
\item (Coverage ceiling) If $0\le\alpha<1$, $S(M,W,\alpha)\le1/(1-\alpha)$.
\item (Width ceiling) If $\alpha\le1$, $S(M,W,\alpha)\le(M+1)/(W+1)$, with equality at $\alpha=1$.
\item (Monotonicity) If $\alpha<\alpha'\le1$, $S(M,W,\alpha)<S(M,W,\alpha')$.
\item (Exchange rate) For $0<W,W'<M$ and $\alpha,\alpha'\le1$: $S(M,W,\alpha)=S(M,W',\alpha')$ iff $(1-\alpha)M+W=(1-\alpha')M+W'$.
\end{enumerate}
\end{theorem}
\begin{proof}[Proof sketch]
All follow from Theorem~\ref{thm:exact} by cross-multiplication of positive quantities: (1) reduces to $-\alpha\le W$; (2) uses $(1-\alpha)M\ge0$; (3) the denominator strictly decreases in $\alpha$; (4) the numerators coincide.
\end{proof}

One cell of width is worth exactly $1/M$ of coverage: at $M=1000$, $(\alpha,W)=(0.90,20)$ and $(0.93,50)$ both give $S=8.2727\ldots$.

\begin{theorem}[Continuum law]\label{thm:cont}
If $1-\alpha+w>0$ and $W_M/M\to w$, then $\dfrac{M+1}{(1-\alpha)M+W_M+1}\to\dfrac1{1-\alpha+w}$.
\end{theorem}
\begin{proof}[Proof sketch]
Divide by $M$: $(1+1/M)/((1-\alpha)+W_M/M+1/M)$.
\end{proof}

The residual $1-\alpha+w$ is the coverage deficit plus the width: the two numbers add.

