\section{Calibrating the $5.19\times$ crossing}

\begin{theorem}[Crossing calibration]\label{thm:cross}
If $0.02\le w\le0.05$, $1-\alpha+w>0$ and $1/(1-\alpha+w)=5.19$, then $0.82<\alpha<0.86$. Moreover $1/(0.1+w)>5.19$ for all $w\in[0.02,0.05]$.
\end{theorem}
\begin{proof}[Proof sketch]
$\alpha=1-1/5.19+w\approx0.80732+w\in[0.8273,0.8573]$; and $1/(0.1+w)\ge1/0.15>6.6$.
\end{proof}

A $90\%$-reliable window of width $2$--$5\%$ is worth $6.67\times$ to $8.33\times$, so the $90\%$ reading overprices the $5.19\times$ gain; the correct coverage is $83$--$86\%$.

\section{The min-law prior}

\begin{theorem}[Counting identity]
For $1\le j\le M$ exactly $2(M-j)+1$ pairs in $\{1,\dots,M\}^2$ have minimum $j$; hence $\mu_M$ is a probability law.
\end{theorem}
\begin{proof}[Proof sketch]
The pairs form the disjoint union $\{j\}\times\{j,\dots,M\}\ \cup\ \{j+1,\dots,M\}\times\{j\}$. Also $\sum_{i=0}^{N-1}(2(M-1-i)+1)=N(2M-N)$, equal to $M^2$ at $N=M$.
\end{proof}

\begin{theorem}[Optimal blind cost]
$\mu_M$ is strictly decreasing, ascending scan is Bayes-optimal, and its cost is $\sum_j j\,\mu_M(j)=\dfrac{(M+1)(2M+1)}{6M}$.
\end{theorem}
\begin{proof}[Proof sketch]
Monotonicity is immediate; optimality is Theorem~\ref{thm:greedy}. By induction $\sum_{i=0}^{N-1}(i+1)(2(M-1-i)+1)=N(N+1)\bigl(\frac{2M+1}2-\frac{2N+1}3\bigr)$; set $N=M$.
\end{proof}

\begin{remark}
By strict monotonicity, conditioning $\mu_M$ on a window of two or more cells is never uniform; ``uniform given a hit'' models are inconsistent with this target law.
\end{remark}

\begin{theorem}[Perfect-coverage block hints]\label{thm:block}
Let $M=kW$. If an oracle names with certainty which of the $k$ consecutive width-$W$ blocks contains $J$ and the searcher scans it in ascending order, the expected cost is $\dfrac{(W+1)(3M-W+1)}{6M}$ and the speedup over optimal blind search is
\[
S_{\min}(M,W)=\frac{(M+1)(2M+1)}{(W+1)(3M-W+1)}\longrightarrow\frac{2}{w(3-w)}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
In block $b$, offset $r$ has probability $(A_b-2r)/M^2$ with $A_b=2M-1-2bW$ and costs $r+1$. The inner sum is $A_b\frac{W(W+1)}2-\frac23(W-1)W(W+1)$; sum the arithmetic progression over $b<k$ and simplify with $M=kW$.
\end{proof}

