from fractions import Fraction
from typing import List, Sequence, Set

def truthful_posterior(prior: Sequence[Fraction], window: Set[int], alpha: Fraction) -> List[Fraction]:
    """Posterior after a truthful interval hint: mass alpha on the window, 1-alpha off it,
    each spread proportionally to the prior."""
    p_in = sum(prior[j] for j in window)
    p_out = sum(prior) - p_in
    return [alpha * prior[j] / p_in if j in window else (1 - alpha) * prior[j] / p_out
            for j in range(len(prior))]

def bayes_optimal_order(post: Sequence[Fraction]) -> List[int]:
    """Greedy order: non-increasing posterior, ties broken by index (rearrangement inequality)."""
    return sorted(range(len(post)), key=lambda j: (-post[j], j))

def expected_probes(post: Sequence[Fraction], order: Sequence[int]) -> Fraction:
    return sum((Fraction(i + 1) * post[c] for i, c in enumerate(order)), Fraction(0))

if __name__ == "__main__":
    M, W = 12, 3
    prior = [Fraction(1, M)] * M
    for alpha in (Fraction(9, 10), Fraction(1, 4), Fraction(1, 5)):
        post = truthful_posterior(prior, set(range(W)), alpha)
        order = bayes_optimal_order(post)
        print(f"alpha={alpha}: order={order}, cost={expected_probes(post, order)}, "
              f"window-first cost={expected_probes(post, range(M))}")

from typing import Optional

def speedup(M: int, W: int, alpha: float) -> float:
    """Exact uniform-prior speedup of window-first search over the blind scan."""
    return (M + 1) / ((1 - alpha) * M + W + 1)

def continuum_speedup(alpha: float, w: float) -> float:
    return 1.0 / (1.0 - alpha + w)

def equivalent_coverage(S_obs: float, w: float) -> Optional[float]:
    """Coverage alpha that a width-w hint needs to explain an observed speedup (continuum law).
    Returns None when no admissible alpha in [w, 1] exists."""
    alpha = 1.0 - 1.0 / S_obs + w
    return alpha if w <= alpha <= 1.0 else None

def equivalent_width(S_obs: float, alpha: float) -> Optional[float]:
    w = 1.0 / S_obs - (1.0 - alpha)
    return w if 0.0 < w <= alpha else None

def exchange_partner(M: int, W: int, alpha: float, W_new: int) -> float:
    """Coverage giving the same speedup at width W_new: (1-a)M + W is invariant."""
    return alpha + (W_new - W) / M

if __name__ == "__main__":
    for w in (0.02, 0.035, 0.05):
        print(f"5.19x at w={w}: alpha*={equivalent_coverage(5.19, w):.4f}; 90% gives {continuum_speedup(0.9, w):.2f}x")
    print("width needed at alpha=0.9:", equivalent_width(5.19, 0.9))
    a2 = exchange_partner(1000, 20, 0.9, 50)
    print(a2, speedup(1000, 20, 0.9), speedup(1000, 50, a2))

import itertools
from fractions import Fraction
from typing import List, Tuple

def hint_posterior(M: int, W: int, alpha: Fraction) -> List[Fraction]:
    return [alpha / W if j < W else (1 - alpha) / (M - W) for j in range(M)]

def cost(q: List[Fraction], order: Tuple[int, ...]) -> Fraction:
    return sum((Fraction(i + 1) * q[c] for i, c in enumerate(order)), Fraction(0))

def verify_threshold(M: int, W: int, alpha: Fraction) -> Tuple[Fraction, Fraction, bool]:
    """Exhaustively compare window-first with the best of all M! orders."""
    q = hint_posterior(M, W, alpha)
    committed = cost(q, tuple(range(M)))
    best = min(cost(q, p) for p in itertools.permutations(range(M)))
    predicted_optimal = alpha * M >= W
    assert (committed == best) == predicted_optimal
    return committed, best, predicted_optimal

if __name__ == "__main__":
    for M in range(3, 8):
        for W in range(1, M):
            for alpha in (Fraction(k, 12) for k in range(13)):
                verify_threshold(M, W, alpha)
    print("threshold alpha >= W/M confirmed for all M <= 7, W < M, alpha in {0,1/12,...,1}")
    print(verify_threshold(6, 2, Fraction(1, 4)))

from fractions import Fraction

def min_law_blind_cost(M: int) -> Fraction:
    """Bayes-optimal (ascending) blind cost under P(J=j) = (2(M-j)+1)/M^2."""
    return Fraction((M + 1) * (2 * M + 1), 6 * M)

def min_law_block_cost(M: int, W: int) -> Fraction:
    """Perfect-coverage aligned block hint (W divides M)."""
    assert M % W == 0
    return Fraction((W + 1) * (3 * M - W + 1), 6 * M)

def min_law_block_cost_direct(M: int, W: int) -> Fraction:
    total = Fraction(0)
    for b in range(M // W):
        for r in range(W):
            j = b * W + r + 1
            total += (r + 1) * Fraction(2 * (M - j) + 1, M * M)
    return total

def min_law_block_speedup(M: int, W: int) -> Fraction:
    return min_law_blind_cost(M) / min_law_block_cost(M, W)

if __name__ == "__main__":
    for M, W in ((200, 4), (1000, 50), (10_000, 200), (10_000, 2000)):
        assert min_law_block_cost(M, W) == min_law_block_cost_direct(M, W)
        w = W / M
        print(f"M={M}, W={W}: S={float(min_law_block_speedup(M, W)):.3f}, continuum {2/(w*(3-w)):.3f}")
